DROP TABLE IF EXISTS `theses`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `theses` (
  `id` int NOT NULL AUTO_INCREMENT,
  `thesis_code` varchar(30) COLLATE utf8mb4_unicode_ci NOT NULL,
  `title` varchar(500) COLLATE utf8mb4_unicode_ci NOT NULL,
  `author_researchers` varchar(500) COLLATE utf8mb4_unicode_ci NOT NULL,
  `program_id` int NOT NULL,
  `year_published` year NOT NULL,
  `abstract` text COLLATE utf8mb4_unicode_ci NOT NULL,
  `keywords` text COLLATE utf8mb4_unicode_ci NOT NULL,
  `research_field` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `research_topic` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `research_subtopic` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `shelf_location` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL,
  `availability` enum('Available','Borrowed') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'Available',
  `is_archived` tinyint(1) NOT NULL DEFAULT '0',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `thesis_code` (`thesis_code`),
  KEY `idx_thesis_title` (`title`(191)),
  KEY `idx_thesis_year` (`year_published`),
  KEY `idx_thesis_field` (`research_field`),
  KEY `idx_thesis_topic` (`research_topic`),
  KEY `idx_thesis_availability` (`availability`),
  KEY `idx_thesis_program` (`program_id`),
  CONSTRAINT `fk_thesis_program` FOREIGN KEY (`program_id`) REFERENCES `programs` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=1002 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

