/*!40000 ALTER TABLE `theses` ENABLE KEYS */;
UNLOCK TABLES;

--
-- Table structure for table `transactions`
--

DROP TABLE IF EXISTS `transactions`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `transactions` (
  `id` int NOT NULL AUTO_INCREMENT,
  `transaction_id` varchar(30) COLLATE utf8mb4_unicode_ci NOT NULL,
  `borrowing_request_id` int NOT NULL,
  `thesis_id` int NOT NULL,
  `date_time_borrowed` datetime NOT NULL,
  `expected_return_time` datetime NOT NULL,
  `borrowing_location` enum('Within Library Only','Outside Library / Campus') COLLATE utf8mb4_unicode_ci NOT NULL,
  `actual_return_time` datetime DEFAULT NULL,
  `status` enum('Borrowed','Returned') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'Borrowed',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `transaction_id` (`transaction_id`),
  UNIQUE KEY `uq_transaction_request` (`borrowing_request_id`),
  KEY `fk_transaction_thesis` (`thesis_id`),
  KEY `idx_transaction_status` (`status`),
  KEY `idx_transaction_borrowed` (`date_time_borrowed`),
  CONSTRAINT `fk_transaction_request` FOREIGN KEY (`borrowing_request_id`) REFERENCES `borrowing_requests` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `fk_transaction_thesis` FOREIGN KEY (`thesis_id`) REFERENCES `theses` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=381 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `transactions`
--

LOCK TABLES `transactions` WRITE;
/*!40000 ALTER TABLE `transactions` DISABLE KEYS */;
